import{bQ as e,aL as a,u as r,G as d}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"核心设计","description":"把委托、持仓、合约账户与风险状态分成相互关联的独立对象。","frontmatter":{"title":"核心设计","description":"把委托、持仓、合约账户与风险状态分成相互关联的独立对象。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/0804"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/0804"}],["meta",{"property":"og:title","content":"核心设计 · TGEX"}],["meta",{"property":"og:description","content":"把委托、持仓、合约账户与风险状态分成相互关联的独立对象。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"核心设计 · TGEX"}],["meta",{"name":"twitter:description","content":"把委托、持仓、合约账户与风险状态分成相互关联的独立对象。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"核心设计\\",\\"description\\":\\"把委托、持仓、合约账户与风险状态分成相互关联的独立对象。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算\\",\\"url\\":\\"https://tgex.net/pages/0804\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/0804\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/0804.md","filePath":"08.合约手册/04.核心设计.md"}'),o={name:"pages/0804.md"};function n(p,t,s,i,h,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">合约手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">把委托、持仓、保证金账户和风险状态分开建模。合法边界见[交易规则](/pages/0803)；谁持运行态见[系统架构](/pages/0802)；统一案例见[业务概述](/pages/0801)。</div><h2 id="position" tabindex="-1">账户与持仓 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;账户与持仓 {#position}&quot;">​</a></h2><p>订单表达待执行意图；持仓表达已成交敞口。撤销未成交的开仓单，<strong>不会</strong>平掉已经建立的持仓。</p><p>持仓通常至少包含：</p><table tabindex="0"><thead><tr><th>字段语义</th><th>含义</th></tr></thead><tbody><tr><td>方向</td><td>多 / 空</td></tr><tr><td>数量</td><td>当前持仓量</td></tr><tr><td>开仓均价</td><td>成本均价口径</td></tr><tr><td>可平数量</td><td>尚允许平仓的数量</td></tr><tr><td>保证金占用</td><td>该仓（或共享模式下的相关）占用</td></tr></tbody></table><p>合约账户（热路径）与现货币币账户分离：划转进合约账户后，才参与开仓占用。权威热态见<a href="/pages/080802">用户合约账户缓存</a>。</p><h2 id="orders" tabindex="-1">订单与持仓状态 <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;订单与持仓状态 {#orders}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>状态在说什么</th></tr></thead><tbody><tr><td>委托</td><td>受理、部分成交、完全成交、已撤销等</td></tr><tr><td>持仓</td><td>是否仍有有效敞口；强平过程中可能有锁定 / 清理态</td></tr></tbody></table><p>二者不能共用一套状态含义。强平需能关联到具体持仓与清算明细，而不是只改一个模糊的「账户状态」。</p><p>阅读数量时建议区分：</p><table tabindex="0"><thead><tr><th>数量概念</th><th>含义</th></tr></thead><tbody><tr><td>委托原始量</td><td>用户提交的开 / 平数量</td></tr><tr><td>已成交量</td><td>累计成交，只增不减</td></tr><tr><td>剩余委托量</td><td>尚未成交部分</td></tr><tr><td>持仓量 / 可平量</td><td>敞口与允许平仓上限</td></tr></tbody></table><h2 id="pnl" tabindex="-1">保证金与盈亏 <a class="header-anchor" href="#pnl" aria-label="Permalink to &quot;保证金与盈亏 {#pnl}&quot;">​</a></h2><p>线性合约教学公式（说明方向，不含乘数与费用）：</p><table tabindex="0"><thead><tr><th>方向</th><th>简化浮盈</th></tr></thead><tbody><tr><td>多仓</td><td>约 <code>数量 ×（参考价 − 开仓均价）</code></td></tr><tr><td>空仓</td><td>约 <code>数量 ×（开仓均价 − 参考价）</code></td></tr></tbody></table><p>参考价在风控与展示上常取<strong>标记价</strong>（以产品为准）。已实现盈亏在平仓成交时落定。手续费、资金费、合约乘数都会改实际权益；业务概述案例可先忽略费用。</p><p>追加 / 减少保证金、调整杠杆会改变风险状态；调整前应检查持仓、未成交委托与维持要求。是否对所有模式开放手动调整，以产品为准。见<a href="/pages/080505">保证金与资金协同</a>。</p><h2 id="risk" tabindex="-1">风险与强平 <a class="header-anchor" href="#risk" aria-label="Permalink to &quot;风险与强平 {#risk}&quot;">​</a></h2><p>风险计算需要稳定的价格与资产口径。权益低于对应维持要求时如何处理，由产品规则与风险引擎决定——<strong>不能</strong>把「亏完初始保证金」写成所有产品的唯一强平条件。</p><p>设计上把三阶段分开：</p><ol><li><strong>触发</strong>：标记价等更新后扫描，命中风险条件</li><li><strong>执行</strong>：限制用户操作、处理冲突委托、提交强平减仓 / 平仓</li><li><strong>确认</strong>：账户与持仓结果落定，留下清算明细</li></ol><p>流程见<a href="/pages/080503">强平与清算</a>。下列细节不在本文固化：部分强平阈值、风险准备金分摊、穿仓补偿顺序——需对照当前合约版本后再写入业务说明。</p><p>同组：<a href="/pages/0801">业务概述</a> · <a href="/pages/0802">系统架构</a> · <a href="/pages/0803">交易规则</a> · <a href="/pages/080503">强平与清算</a> · <a href="/pages/080801">缓存总览</a></p>',24)])])}const b=e(o,[["render",n]]);export{c as __pageData,b as default};
